    fn parts_with_forwarded_proto(proto: Option<&str>) -> http::request::Parts {
        let (mut parts, _) = http::Request::new(()).into_parts();
        if let Some(p) = proto {
            parts
                .headers
                .insert("x-forwarded-proto", http::HeaderValue::from_str(p).unwrap());
        }
        parts
    }

