    #[test]
    fn a_cursor_with_both_handle_and_offset_resumes() {
        let params = HashMap::from([
            ("handle".to_owned(), "h-1".to_owned()),
            ("offset".to_owned(), "17".to_owned()),
        ]);
        assert_eq!(
